/******************************************************************************/
/***                           Stored Procedures                            ***/
/******************************************************************************/


SET TERM ^ ;

ALTER PROCEDURE EFD_0000 (
    DATA1 DATE,
    DATA2 DATE,
    LOJA INTEGER)
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    COD_VER VARCHAR(4),
    COD_FIN INTEGER,
    DT_INI VARCHAR(8),
    DT_FIN VARCHAR(8),
    NOME VARCHAR(100),
    CNPJ VARCHAR(14),
    CPF VARCHAR(11),
    UF VARCHAR(2),
    IE VARCHAR(14),
    COD_MUN VARCHAR(7),
    IM VARCHAR(15),
    SUFRAMA VARCHAR(9),
    IND_PERFIL VARCHAR(1),
    IND_ATIV VARCHAR(1),
    FIM INTEGER)
AS
declare variable TIPOATIVIDADE integer;
BEGIN
 --- Versao 21.Junho.2013

 --- Deleta tabelas temporarias do SPED.
     DELETE FROM CONTADORES;
     DELETE FROM TB_ECFA170;
     DELETE FROM TB_ECFC110;
     DELETE FROM TB_ECFC120;
     DELETE FROM TB_ECFC140;
     DELETE FROM TB_ECFC141;
     DELETE FROM TB_ECFC170;
     DELETE FROM TB_ECFC190;
     DELETE FROM TB_ECFC195;
     DELETE FROM TB_ECFC197;
     DELETE FROM TB_ECFC405;
     DELETE FROM TB_ECFC420;
     DELETE FROM TB_ECFC460;
     DELETE FROM TB_ECFC470;
     DELETE FROM TB_ECFC481;
     DELETE FROM TB_ECFC485;
     DELETE FROM TB_ECFC490;
     DELETE FROM TB_ECFC490ECF;
     DELETE FROM TB_ECFC49X_ECF;
     DELETE FROM TB_ECFC491;
     DELETE FROM TB_ECFC495;
     DELETE FROM TB_ECFD110;
     DELETE FROM TB_ECFD190;
     DELETE FROM TB_ECFD201;
     DELETE FROM TB_ECFD205;
     DELETE FROM TB_ECFD590;
     DELETE FROM TB_ECFE210;
     DELETE FROM TB_ECFM410;
     DELETE FROM TB_ECFM810;
     DELETE FROM TB_ECFC100;
     DELETE FROM TB_ECFC100COMPRAS;
     DELETE FROM TB_ECFC100VENDAS;

     REG = '0000';

     IF (:DATA1 >= '01.01.2015') THEN COD_VER = '009';
     IF (:DATA1 BETWEEN '01.01.2013' AND '31.12.2014') THEN COD_VER = '008';
     IF (:DATA1 BETWEEN '30.06.2012' AND '31.12.2012') THEN COD_VER = '006';
     IF (:DATA1 BETWEEN '01.01.2012' AND '29.06.2012') THEN COD_VER = '005';
     IF (:DATA1 BETWEEN '01.01.2011' AND '31.12.2011') THEN COD_VER = '004';
     IF (:DATA1 BETWEEN '01.01.2010' AND '31.12.2010') THEN COD_VER = '003';
     IF (:DATA1 BETWEEN '01.01.2009' AND '31.12.2009') THEN COD_VER = '002';
     IF (:DATA1 <= '31.12.2008') THEN COD_VER = '001';

     COD_FIN = '0';
     DT_INI = SUBSTRING(CAST(:DATA1 AS DATE) FROM 9 FOR 2) || SUBSTRING(CAST(:DATA1 AS DATE) FROM 6 FOR 2) || SUBSTRING(CAST(:DATA1 AS DATE) FROM 1 FOR 4);
     DT_FIN = SUBSTRING(CAST(:DATA2 AS DATE) FROM 9 FOR 2) || SUBSTRING(CAST(:DATA2 AS DATE) FROM 6 FOR 2) || SUBSTRING(CAST(:DATA2 AS DATE) FROM 1 FOR 4);

     IND_PERFIL = 'A';
     IND_ATIV = '1';

     SELECT
         SUBSTRING (RAZAOSOCIAL FROM 1 FOR 99),
         CGC AS CNPJ,
         UF,
         SUBSTRING (IE FROM 1 FOR 14),
         CODCIDADEIBGE,
         IM,
         TIPOATIVIDADE
         FROM EMPRESA
     WHERE CODLOJA = :LOJA
     INTO :NOME, :CNPJ, :UF, :IE, :COD_MUN, :IM, :TIPOATIVIDADE;

 --------------------------------------------- GERA DADOS PARA TABELAS EFD

    INSERT INTO TB_ECFC100COMPRAS
      (LOJA, CODCOMPRA, STATUS, CNPJ, IE, DATA, UF, MODELO, CHV_NFE, SERIE, SUBSERIE,
      NUMERO, CFOP, EMITENTE, SITTRIB, NUMITEM, CODPRODUTO, QUANTIDADE, PRECOBRUTO,
      DESCONTO, OUTRASDESPESAS, VALORFRETEREAL, VALORTOTAL, BASEICMS, BASEICMSST,
      VALORICMS, VALORICMSST, ISENTAS, OUTRAS, ALIQUOTAICMS, ALIQUOTAICMSST, ALIQUOTAIPI,
      BASEIPI, VALORIPI, SITUACAO, CODANTECIPACAOTRIBUTARIA, MODALIDADEFRETE,
      NFSERVICOTRANSPORTE, CODIGONCM, DESCRICAO, CODEMBALAGEM, REDUCAOBASEICMS,
      DATASTATUS, BASEICMSSTC195, VALORICMSSTC195)
    SELECT
      LOJA, CODCOMPRA, STATUS, CNPJ, IE, DATA, UF, MODELO, CHV_NFE, SERIE, SUBSERIE,
      NUMERO, CFOP, EMITENTE, SITTRIB, NUMITEM, CODPRODUTO, QUANTIDADE,
      CASE
        WHEN (DESCONTO < 0) THEN PRECOBRUTO + DESCONTO
        ELSE PRECOBRUTO
      END AS VL_ITEM,
       CASE
         WHEN (DESCONTO < 0) THEN 0
         ELSE DESCONTO
       END AS VL_DESC,
       OUTRASDESPESAS, VALORFRETEREAL, VALORTOTAL, BASEICMS, BASEICMSST, VALORICMS,
       VALORICMSST, ISENTAS, OUTRAS, ALIQUOTAICMS, ALIQUOTAICMSST, ALIQUOTAIPI, BASEIPI,
       VALORIPI, SITUACAO, CODANTECIPACAOTRIBUTARIA, MODALIDADEFRETE, NFSERVICOTRANSPORTE,
       CODIGONCM, DESCRICAO, CODEMBALAGEM, REDUCAOBASEICMS, DATASTATUS,
       BASEICMSSTC195, VALORICMSSTC195
    FROM EFD_C100COMPRAS (:LOJA, :DATA1, :DATA2)
    WHERE CODPRODUTO IS NOT NULL;
   -----
