        EMITENTE, NUMERO, CFOP, SITTRIB, SITTRIBIPI, SITTRIBPIS, SITTRIBCOFINS, NUMITEM,
        TIPOPRODUTO, CODPRODUTO, QUANTIDADE, PRECOBRUTO, DESCONTODESPESA, VALORTOTAL, BASEICMS,
