ALTER PROCEDURE EFD_0005 (
    LOJA INTEGER)
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    FANTASIA VARCHAR(60),
    CEP VARCHAR(8),
    END_ VARCHAR(60),
    NUM VARCHAR(10),
    COMPL VARCHAR(60),
    BAIRRO VARCHAR(60),
    FONE VARCHAR(11),
    FAX VARCHAR(11),
    EMAIL VARCHAR(40),
    FIM VARCHAR(1))
AS
BEGIN
    REG = '0005';
    FOR SELECT
           SUBSTRING (NOMEFANTASIA FROM 1 FOR 60),
           SUBSTRING (CEP FROM 1 FOR 8),
           SUBSTRING (ENDERECO FROM 1 FOR 60),
           SUBSTRING (COMPLEMENTO FROM 1 FOR 60),
           SUBSTRING (BAIRRO FROM 1 FOR 60),
           SUBSTRING (FONE FROM 1 FOR 10),
           SUBSTRING (FAX FROM 1 FOR 10),
           SUBSTRING (EMAIL FROM 1 FOR 40)
         FROM EMPRESA
         WHERE CODLOJA = :LOJA
         INTO :FANTASIA, :CEP, :END_, :COMPL, :BAIRRO, :FONE, :FAX, :EMAIL
    DO SUSPEND;
END^


ALTER PROCEDURE EFD_0015 (
    LOJA INTEGER)
RETURNS (
    INI INTEGER,
    REG VARCHAR(4),
    UF_ST VARCHAR(2),
    IE_ST VARCHAR(14),
    FIM INTEGER)
AS
BEGIN
    REG = '0015';

    SELECT
        SUBSTRING (UF FROM 1 FOR 2),
        SUBSTRING (IE  FROM 1 FOR 14)
    FROM EMPRESA WHERE CODLOJA = :LOJA
    INTO :UF_ST, :IE_ST;

    SUSPEND;
END^


ALTER PROCEDURE EFD_0100 (
    LOJA INTEGER)
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    NOME VARCHAR(60),
    CPF VARCHAR(11),
    CRC VARCHAR(15),
    CNPJ VARCHAR(14),
    CEP VARCHAR(8),
    ENDERECO VARCHAR(60),
    NUM VARCHAR(10),
    COMPL VARCHAR(10),
    BAIRRO VARCHAR(50),
    FONE VARCHAR(20),
    FAX VARCHAR(10),
    EMAIL VARCHAR(100),
    COD_MUN VARCHAR(10),
    FIM VARCHAR(10))
AS
BEGIN
REG = '0100';

SELECT
  CGCCONTADOR
FROM EMPRESA
WHERE CODLOJA = :LOJA
INTO :CPF;

SELECT
    RAZAOSOCIAL,
    CNPJMATRIZ,
    INSCESTADUAL,
    CEP,
    ENDERECO,
    '' AS NUM,
    '' AS COMPL,
    BAIRRO,
    DDD||FONE,
    FAX,
    EMAIL,
    CODCIDADEIBGE
FROM CLIENTES
WHERE CGC = :CPF
INTO :NOME, :CNPJ, :CRC, :CEP, :ENDERECO, :NUM, :COMPL, :BAIRRO, :FONE,:FAX, :EMAIL, COD_MUN;
  SUSPEND;
END^


ALTER PROCEDURE EFD_0150
RETURNS (
    INI INTEGER,
    REG VARCHAR(10),
    COD_PART VARCHAR(60),
    NOME VARCHAR(100),
    COD_PAIS VARCHAR(5),
    CNPJ VARCHAR(14),
    CPF VARCHAR(11),
    IE VARCHAR(14),
    COD_MUN VARCHAR(7),
    SUFRAMA VARCHAR(9),
    ENDERECO VARCHAR(60),
    NUM VARCHAR(10),
    COMPL VARCHAR(60),
    BAIRRO VARCHAR(60),
    FIM INTEGER)
AS
declare variable vcnpj varchar(14);
BEGIN
---------------------------- CADASTRO DE PARTICIPANTES
    REG = '0150';
    CNPJ = NULL;
-------------------------------------------------------------------- CLIENTES
    FOR SELECT
          CNPJ
        FROM TB_ECFC100VENDAS A
        WHERE EXISTS (SELECT * FROM CLIENTES C WHERE C.CGC = A.CNPJ)
        AND STATUS NOT IN (9,10,12,15)
        AND COALESCE (STATUSNFE,0) NOT IN (101,102)
        AND A.CNPJ IS NOT NULL
        GROUP BY CNPJ
        INTO :VCNPJ
    DO BEGIN

       SELECT

          SUBSTRING(CGC FROM 1 FOR 60) AS COD_PART,

          SUBSTRING(RAZAOSOCIAL FROM 1 FOR 60),

          CODPAIS AS COD_PAIS,

           CASE
             WHEN (SUBSTRING (CODCIDADEIBGE FROM 1 FOR 60) = '9999999' OR COALESCE (CODPAIS, '1058') <> '1058') THEN ''
             WHEN (SUBSTRING(CGC FROM 12 FOR 13) <> '') THEN CGC
             ELSE ''
           END AS CNPJ,

           CASE
             WHEN (SUBSTRING (CODCIDADEIBGE FROM 1 FOR 60) = '9999999' OR COALESCE (CODPAIS, '1058')  <> '1058') THEN ''
             WHEN (SUBSTRING (CGC FROM 12 FOR 13) = '') THEN CGC
           ELSE '' END AS CPF,

          CASE
             WHEN (INSCESTADUAL LIKE '%ISENTO%' OR SUBSTRING (CGC FROM 12 FOR 13) = '') THEN ''
              ELSE SUBSTRING(INSCESTADUAL FROM 1 FOR 14)
          END,

         SUBSTRING(CODCIDADEIBGE FROM 1 FOR 60),

         SUBSTRING (ENDERECO FROM 1 FOR 60),

         '' AS NUMERO,

         '' AS COMPLEMENTO,

         SUBSTRING (BAIRRO FROM 1 FOR 60)

       FROM CLIENTES WHERE CGC = :VCNPJ
       INTO :COD_PART, :NOME, :COD_PAIS, :CNPJ, :CPF, :IE, :COD_MUN, :ENDERECO, :NUM, :COMPL, :BAIRRO;

       SUSPEND;
       END

------------------------------------------------------------------ FORNECEDORES
    FOR SELECT
           CNPJ
        FROM TB_ECFC100COMPRAS A
        WHERE NOT EXISTS (SELECT * FROM TB_ECFC100VENDAS C WHERE C.CNPJ = A.CNPJ
                          AND STATUS NOT IN (9,10,12,15)
                          AND A.CNPJ IS NOT NULL)
        AND A.CNPJ IS NOT NULL
        AND A.MODELO <> '06'
        GROUP BY CNPJ
        INTO :VCNPJ

    DO BEGIN
       SELECT FIRST 1

           SUBSTRING(CGC FROM 1 FOR 60) AS COD_PART,

           SUBSTRING(RAZAOSOCIAL FROM 1 FOR 60),

           '1058' AS COD_PAIS,

           CASE
              WHEN (SUBSTRING(CGC FROM 12 FOR 13) <> '') THEN CGC
              ELSE ''
           END AS CNPJ,

           CASE
              WHEN SUBSTRING(CODCIDADEIBGE FROM 1 FOR 60) = '9999999' THEN ''
              WHEN (SUBSTRING(CGC FROM 12 FOR 13) = '') THEN CGC
              ELSE ''
            END AS CPF,

           CASE
              WHEN IE LIKE '%ISENTO%' THEN ''
              ELSE SUBSTRING(IE FROM 1 FOR 14)
           END,

           COALESCE (CODCIDADEIBGE,0) AS CODMUNICIPIOIBGE,

           SUBSTRING (ENDERECO FROM 1 FOR 60),

           '' AS NUMERO,

           '' AS COMPLEMENTO,

           SUBSTRING (BAIRRO FROM 1 FOR 60)

       FROM FORNECEDORES WHERE CGC = :VCNPJ
       INTO :COD_PART, :NOME, :COD_PAIS, :CNPJ, :CPF, :IE, :COD_MUN, :ENDERECO, :NUM, :COMPL, :BAIRRO;

       SUSPEND;
       END

END^


ALTER PROCEDURE EFD_0190 (
    LOJA INTEGER,
    DT DATE)
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    UNID VARCHAR(6),
    DESCR VARCHAR(60),
    FIM VARCHAR(1))
AS
BEGIN ----------------------------------------- CADASTRO DE EMBALAGENS
     REG = '0190';
     FOR
         SELECT
            UPPER (SUBSTRING(CODEMBALAGEM FROM 1 FOR 6))   -- VENDAS
         FROM TB_ECFC100VENDAS
         WHERE NUMITEM NOT IN (991,999)
         AND (SUBSTRING (COALESCE (MODELO,0) FROM 1 FOR 2) IN ('01','1B','04') OR
             (SUBSTRING (COALESCE (MODELO,0) FROM 1 FOR 2) IN ('55') AND EMITENTE = 'T'))
         AND CODPRODUTO NOT LIKE 'S%'
  
         UNION
  
         SELECT
            UPPER(SUBSTRING(CODEMBALAGEM FROM 1 FOR 6))      -- CUPONS
         FROM PRODUTOS P
         JOIN TB_ECFC490ECF A ON (P.CODPRODUTO = A.CODPRODUTO)
         WHERE A.CODPRODUTO NOT LIKE 'S%'
  
         UNION
  
         SELECT
            UPPER(SUBSTRING(P.CODEMBALAGEM FROM 1 FOR 6)) -- COMPRAS
         FROM PRODUTOS P
         JOIN TB_ECFC100COMPRAS A ON (P.CODPRODUTO = A.CODPRODUTO)
         WHERE NUMITEM NOT IN (991,999)
         AND SUBSTRING(COALESCE(MODELO,0) FROM 1 FOR 2) IN ('01','1B','04','55')
         AND EMITENTE = 'T'

         UNION

         SELECT
            UPPER(SUBSTRING(P.CODEMBALAGEM FROM 1 FOR 6))        -- INVENTARIO
         FROM PRODUTOS P
         JOIN EFD_H010 (:LOJA,:DT) A ON (P.CODPRODUTO = A.COD_ITEM)
         GROUP BY 1
         ORDER BY 1
         INTO :UNID

     DO BEGIN
          SELECT
             SUBSTRING (E.EMBALAGEM FROM 1 FOR 60)
          FROM EMBALAGEM E
          WHERE E.CODEMBALAGEM = :UNID
          INTO :DESCR;
        SUSPEND;
     END
END^


ALTER PROCEDURE EFD_0200 (
    LOJA INTEGER,
    DT DATE)
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    COD_ITEM VARCHAR(50),
    DESCR_ITEM VARCHAR(100),
    COD_BARRA VARCHAR(15),
    COD_ANT_ITEM INTEGER,
    UNID_INV VARCHAR(6),
    TIPO_ITEM VARCHAR(2),
    COD_NCM VARCHAR(8),
    EX_IPI VARCHAR(3),
    COD_GEN VARCHAR(2),
    COD_LST VARCHAR(4),
    ALIQ_ICMS DOUBLE PRECISION,
    FIM VARCHAR(1))
AS
BEGIN ------------------------------------ CADASTRO DE PRODUTOS
     REG = '0200';

     FOR
         SELECT
             SUBSTRING (CODPRODUTO FROM 1 FOR 20)        -- VENDAS
         FROM TB_ECFC100VENDAS
         WHERE NUMITEM NOT IN (991,999)
         AND (SUBSTRING (COALESCE (MODELO,0) FROM 1 FOR 2) IN ('01','1B','04') OR
             (SUBSTRING (COALESCE (MODELO,0) FROM 1 FOR 2) IN ('55') AND EMITENTE = 'T'))
         AND CODPRODUTO NOT LIKE 'S%'

         UNION

         SELECT
             SUBSTRING (CODPRODUTO FROM 1 FOR 20)        -- CUPONS
         FROM TB_ECFC490ECF
         WHERE CODPRODUTO NOT LIKE 'S%'
         AND STATUS <> 9

         UNION

         SELECT
             SUBSTRING(CODPRODUTO FROM 1 FOR 20)        -- COMPRAS
         FROM TB_ECFC100COMPRAS
         WHERE NUMITEM NOT IN (991,999)
         AND CODPRODUTO NOT LIKE 'S%'
         AND SUBSTRING(COALESCE(MODELO,0) FROM 1 FOR 2) IN ('01','1B','04','55','07','7')
         AND EMITENTE = 'T'

         UNION

         SELECT
             SUBSTRING (COD_ITEM FROM 1 FOR 20)        -- INVENTARIO
         FROM EFD_H010(:LOJA,:DT)
         GROUP BY 1
         ORDER BY 1
         INTO :COD_ITEM

    DO BEGIN
        SELECT
             DESCRICAO,
             SUBSTRING (CODBARRAS FROM 1 FOR 10),
             CODEMBALAGEM AS NID_INV,
             '00' AS TIPO_ITEM,
             CASE
                WHEN P.SITTRIB = '0S0' THEN ' '
                ELSE SUBSTRING (P.NBM FROM 1 FOR 8)
             END AS COD_NCM,
             ICMS AS ALIQ_ICMS
        FROM PRODUTOS P
        WHERE CODPRODUTO = :COD_ITEM
        INTO :DESCR_ITEM, :COD_BARRA, :UNID_INV, :TIPO_ITEM, :COD_NCM, :ALIQ_ICMS;

        SUSPEND;
        END

------------------------------------ CADASTRO DE SERVICOS
     FOR
         SELECT
             SUBSTRING(CODPRODUTO FROM 1 FOR 20)        -- VENDAS
         FROM TB_ECFC100VENDAS
         WHERE NUMITEM NOT IN (991,999)
--         AND SUBSTRING(COALESCE(MODELO,0) FROM 1 FOR 2) IN ('01','1B','04')
         AND CODPRODUTO LIKE 'S%'

         UNION

         SELECT
             SUBSTRING(CODPRODUTO FROM 1 FOR 20)        -- CUPONS
         FROM TB_ECFC490ECF
         WHERE STATUS <> 9
         AND CODPRODUTO LIKE 'S%'
         GROUP BY 1
         ORDER BY 1
         INTO :COD_ITEM

     DO BEGIN
        SELECT
            DESCRICAO,
            '0' AS CODBARRAS,
            CODEMBALAGEM AS NID_INV,
            '00' AS TIPO_ITEM,
            '0',
            '0'
         FROM SERVICOS S
         WHERE CODSERVICO = SUBSTRING (:COD_ITEM FROM 2 FOR 10)
         INTO :DESCR_ITEM, :COD_BARRA, :UNID_INV, :TIPO_ITEM, :COD_NCM, :ALIQ_ICMS;
        SUSPEND;
       END
END^


ALTER PROCEDURE EFD_0400
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    COD_NAT VARCHAR(4),
    DESCR_NAT VARCHAR(250),
    FIM VARCHAR(1))
AS
BEGIN ---------------- TABELA DE NATUREZA DA OPERACAO/PRESTACAO
     REG = '0400';
     FOR
         SELECT    --- VENDAS
            CFOP
         FROM TB_ECFC100VENDAS
         WHERE (SUBSTRING (COALESCE (MODELO,0) FROM 1 FOR 2) IN ('01','1B','04') OR
               (SUBSTRING (COALESCE (MODELO,0) FROM 1 FOR 2) IN ('55') AND EMITENTE = 'T'))

         UNION

         SELECT   --- COMPRAS
            A.CFOP
         FROM  TB_ECFC100COMPRAS A
         WHERE SUBSTRING(COALESCE(MODELO,0) FROM 1 FOR 2) IN ('01','1B','04','55')
         AND NUMITEM NOT IN (991,999)
         AND EMITENTE = 'T'
         GROUP BY 1
         ORDER BY 1
         INTO :COD_NAT

     DO BEGIN
           SELECT
              FIRST 1 SUBSTRING(NATUREZAOPERACAO FROM 1 FOR 60)
           FROM CFOP
           WHERE CFOPN = :COD_NAT
           INTO :DESCR_NAT;
        SUSPEND;
     END
END^


ALTER PROCEDURE EFD_0450 (
    LOJAP INTEGER)
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    COD_INF INTEGER,
    TXT VARCHAR(100),
    FIN VARCHAR(1))
AS
BEGIN ------------------------------------ CADASTRO DE OBSERVACOES
  FOR
      SELECT
        '0450' AS REG,
        C.CODCOMPRA AS COD_INF,
        REPLACE(C1.OBS,'',' ')AS TXT
      FROM TB_ECFC100COMPRAS C
      JOIN COMPRAS C1 ON (C1.CODCOMPRA = C.CODCOMPRA AND C1.LOJA = C.LOJA)
      AND C.LOJA = :LOJAP
      AND COALESCE (C1.OBS,'') <> ''
      GROUP BY 1,2,3
      INTO :REG, :COD_INF, :TXT
      ---- Retirar do gerenciador de exportacoes do SPED
  DO
    SUSPEND;
END^


ALTER PROCEDURE EFD_0460
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    COD_OBS INTEGER,
    TXT VARCHAR(100),
    FIN VARCHAR(1))
AS
BEGIN
  IF (EXISTS (SELECT * FROM TB_ECFC100COMPRAS
              WHERE VALORICMSSTC195 IS NOT NULL)) THEN
  BEGIN
    REG = '0460';
    COD_OBS = 1;
    TXT = 'ICMS ST JA RECOLHIDO ANTERIORMENTE';
    SUSPEND;
  END
END^


ALTER PROCEDURE EFD_0990
RETURNS (
    INI INTEGER,
    REG VARCHAR(4),
    QTD_LIN_0 INTEGER,
    FIM INTEGER)
AS
BEGIN

     SELECT
        '0990' AS REG, 
        SUM(QTDE)
     FROM CONTADORES
     INTO :REG, :QTD_LIN_0;

     SUSPEND;
END^


ALTER PROCEDURE EFD_0990_CONTAREGISTRO (
    LOJA INTEGER,
    DT DATE)
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    QTD_LIN_0 INTEGER,
    FIM VARCHAR(1))
AS
declare variable VQTD_LIN_0 integer;
BEGIN
     DELETE FROM CONTADORES WHERE REG = '0000';
     INSERT INTO CONTADORES VALUES ('0000',1);

     DELETE FROM CONTADORES WHERE REG = '0001';
     INSERT INTO CONTADORES SELECT '0001', COUNT(*) FROM EFD_0001;

     DELETE FROM CONTADORES WHERE REG = '0005';
     INSERT INTO CONTADORES SELECT '0005', COUNT(*) FROM EFD_0005(:LOJA);

     DELETE FROM CONTADORES WHERE REG = '0015';
     INSERT INTO CONTADORES SELECT '0015', COUNT(*) FROM EFD_0015(:LOJA);

     DELETE FROM CONTADORES WHERE REG = '0100';
     INSERT INTO CONTADORES SELECT '0100', COUNT(*) FROM EFD_0100(:LOJA);

     DELETE FROM CONTADORES WHERE REG = '0150';
     INSERT INTO CONTADORES SELECT '0150', COUNT(*) FROM EFD_0150;

     DELETE FROM CONTADORES WHERE REG = '0190';
     INSERT INTO CONTADORES SELECT '0190', COUNT(*) FROM EFD_0190(:LOJA,:DT);

     DELETE FROM CONTADORES WHERE REG = '0200';
     INSERT INTO CONTADORES SELECT '0200', COUNT(*) FROM EFD_0200(:LOJA,:DT);

     DELETE FROM CONTADORES WHERE REG = '0400';
     INSERT INTO CONTADORES SELECT '0400', COUNT(*) FROM EFD_0400;

     DELETE FROM CONTADORES WHERE REG = '0460';
     INSERT INTO CONTADORES SELECT '0460', COUNT(*) FROM EFD_0460;

     DELETE FROM CONTADORES WHERE REG = '0990';
     INSERT INTO CONTADORES (REG, QTDE) VALUES ('0990',1);


    BEGIN
    FOR
     SELECT
        '0990' AS REG, 
        SUM (QTDE)
     FROM CONTADORES
     WHERE CONTADORES.REG IN ('0000','0001','0005','0015','0100','0150','0190','0200','0400',
                              '0450','0460')
     INTO :REG, :VQTD_LIN_0

    DO

    QTD_LIN_0 = :VQTD_LIN_0 + 1;

     SUSPEND;
    END
END^


