            :VL_BC_ICMS_ST,
            :VL_ICMS_ST,
            :VL_IPI ,
            :VL_RED_BC
       DO
       BEGIN
            COD_OBS='';

            SUSPEND;

--            INSERT INTO TB_ECFE190 VALUES (:NUMERONF,:TIPO);

       END
