ALTER PROCEDURE EFD_E200 (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    INI INTEGER,
    REG VARCHAR(4),
    UF VARCHAR(2),
    DT_INI VARCHAR(8),
    DT_FIN VARCHAR(8),
    FIM INTEGER)
AS
declare variable vcnpj varchar(14);
BEGIN   ----------------------------CADASTRO DE PARTICIPANTES
    REG = 'E200';
    DT_INI = SUBSTRING(CAST(:DATA1 AS DATE) FROM 9 FOR 2) || SUBSTRING(CAST(:DATA1 AS DATE) FROM 6 FOR 2) || SUBSTRING(CAST(:DATA1 AS DATE) FROM 1 FOR 4);
    DT_FIN = SUBSTRING(CAST(:DATA2 AS DATE) FROM 9 FOR 2) || SUBSTRING(CAST(:DATA2 AS DATE) FROM 6 FOR 2) || SUBSTRING(CAST(:DATA2 AS DATE) FROM 1 FOR 4);

-------------------------------------------------------------------- CLIENTES
    FOR SELECT
           A.UF
        FROM TB_ECFC100VENDAS A
        WHERE STATUS NOT IN (9,10,12,15)
        AND A.CNPJ IS NOT NULL
        AND (A.VALORICMSST > 0)
        GROUP BY A.UF
        INTO :UF
        DO BEGIN
            SUSPEND;
           END
------------------------------------------------------------------FORNECEDORES
    FOR SELECT
          A.UF
        FROM TB_ECFC100COMPRAS A
        WHERE NOT EXISTS (SELECT * FROM TB_ECFC100VENDAS C WHERE C.CNPJ = A.CNPJ)
        AND A.VALORICMSST > 0
        AND A.CNPJ IS NOT NULL
        GROUP BY A.UF
        INTO :UF

    DO BEGIN
        SUSPEND;
       END

END^


ALTER PROCEDURE EFD_E210 (
    UF VARCHAR(2))
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    IND_MOV_ST INTEGER,
    VL_SLD_CRED_ANT_ST DOUBLE PRECISION,
    VL_DEVOL_ST DOUBLE PRECISION,
    VL_RESSARC_ST DOUBLE PRECISION,
    VL_OUT_CRED_ST DOUBLE PRECISION,
    VL_AJ_CREDITOS_ST DOUBLE PRECISION,
    VL_RETENCAO_ST DOUBLE PRECISION,
    VL_OUT_DEB_ST DOUBLE PRECISION,
    VL_AJ_DEBITOS_ST DOUBLE PRECISION,
    VL_SLD_DEV_ANT_ST DOUBLE PRECISION,
    VL_DEDUCOES_ST DOUBLE PRECISION,
    VL_ICMS_RECOL_ST DOUBLE PRECISION,
    VL_SLD_CRED_ST_TRANSPORTAR DOUBLE PRECISION,
    DEB_ESP_ST DOUBLE PRECISION,
    FIM VARCHAR(1),
    LOJAP INTEGER)
AS
declare variable prazomedio double precision;
declare variable dt_ini date;
declare variable dt_fin date;
declare variable data1 date;
declare variable data2 date;
BEGIN   ---------------------------- CADASTRO DE PARTICIPANTES
    REG = 'E210';
    DT_INI = SUBSTRING(CAST(:DATA1 AS DATE) FROM 9 FOR 2) || SUBSTRING(CAST(:DATA1 AS DATE) FROM 6 FOR 2) || SUBSTRING(CAST(:DATA1 AS DATE) FROM 1 FOR 4);
    DT_FIN = SUBSTRING(CAST(:DATA2 AS DATE) FROM 9 FOR 2) || SUBSTRING(CAST(:DATA2 AS DATE) FROM 6 FOR 2) || SUBSTRING(CAST(:DATA2 AS DATE) FROM 1 FOR 4);
    IND_MOV_ST = 1;
-------------------------------------------------------------------- CLIENTES
    FOR 
       SELECT
          SUM (VL_SLD_CRED_ANT_ST) AS VL_SLD_CRED_ANT_ST,
          SUM (VL_DEVOL_ST) AS VL_DEVOL_ST,
          SUM (VL_RESSARC_ST) AS VL_RESSARC_ST,
          SUM (VL_OUT_CRED_ST) AS VL_OUT_CRED_ST,
          SUM (VL_AJ_CREDITOS_ST) AS VL_AJ_CREDITOS_ST,
          SUM (VL_RETENCAO_ST) AS VL_RETENCAO_ST,
          SUM (VL_OUT_DEB_ST) AS VL_OUT_DEB_ST,
          SUM (VL_AJ_DEBITOS_ST) AS VL_AJ_DEBITOS_ST,
          SUM (VL_SLD_DEV_ANT_ST) AS VL_SLD_DEV_ANT_ST,
          SUM (VL_DEDUCOES_ST) AS VL_DEDUCOES_ST,
          SUM (VL_ICMS_RECOL_ST) AS VL_ICMS_RECOL_ST,
          SUM (VL_SLD_CRED_ST_TRANSPORTAR) AS VL_SLD_CRED_ST_TRANSPORTAR,
          SUM (DEB_ESP_ST) AS DEB_ESP_ST
       FROM    (SELECT
                   C.UF,
                   0 AS VL_SLD_CRED_ANT_ST,
                   0 AS VL_DEVOL_ST,
                   0 AS VL_RESSARC_ST,
                   0 AS VL_OUT_CRED_ST,
                   0 AS VL_AJ_CREDITOS_ST,
                   A.VALORICMSST AS VL_RETENCAO_ST,
                   0 AS VL_OUT_DEB_ST,
                   0 AS VL_AJ_DEBITOS_ST,
                   A.VALORICMSST AS VL_SLD_DEV_ANT_ST,
                   0 AS VL_DEDUCOES_ST,
                   A.VALORICMSST AS VL_ICMS_RECOL_ST,
                   0 AS VL_SLD_CRED_ST_TRANSPORTAR,
                   0 AS DEB_ESP_ST
                FROM TB_ECFC100VENDAS A
        JOIN CLIENTES C ON (C.CGC = A.CNPJ)
        WHERE STATUS NOT IN (9,10,12,15)
        AND A.CNPJ IS NOT NULL
        AND (A.VALORICMSST >0 OR A.SITTRIB LIKE '%60')
        AND C.UF = :UF
        AND A.VALORICMSST > 0)
        GROUP BY UF

       INTO :VL_SLD_CRED_ANT_ST, :VL_DEVOL_ST, :VL_RESSARC_ST, :VL_OUT_CRED_ST, :VL_AJ_CREDITOS_ST,
            :VL_RETENCAO_ST, :VL_OUT_DEB_ST, :VL_AJ_DEBITOS_ST, :VL_SLD_DEV_ANT_ST, :VL_DEDUCOES_ST,
            :VL_ICMS_RECOL_ST, :VL_SLD_CRED_ST_TRANSPORTAR, :DEB_ESP_ST
    DO BEGIN
         INSERT INTO TB_ECFE210 VALUES (:INI,:REG,:IND_MOV_ST,:VL_SLD_CRED_ANT_ST, :VL_DEVOL_ST,
         :VL_RESSARC_ST, :VL_OUT_CRED_ST, :VL_AJ_CREDITOS_ST, :VL_RETENCAO_ST, :VL_OUT_DEB_ST,
         :VL_AJ_DEBITOS_ST, :VL_SLD_DEV_ANT_ST, :VL_DEDUCOES_ST, :VL_ICMS_RECOL_ST,
         :VL_SLD_CRED_ST_TRANSPORTAR, :DEB_ESP_ST,:FIM,:lojap);

       SUSPEND;

       END
------------------------------------------------------------------FORNECEDORES


END^


ALTER PROCEDURE EFD_E990 (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    QTD_LIN_E INTEGER,
    FIM VARCHAR(1))
AS
declare variable vqtd_lin_e integer;
BEGIN

     DELETE FROM CONTADORES WHERE REG = 'E001';
     INSERT INTO CONTADORES SELECT 'E001', COUNT(*) FROM EFD_E001;

     DELETE FROM CONTADORES WHERE REG = 'E100';
     INSERT INTO CONTADORES
      SELECT 'E100', COUNT(*) FROM (SELECT * FROM EFD_E100 (:DATA1,:DATA2));

     DELETE FROM CONTADORES WHERE REG = 'E200';
     INSERT INTO CONTADORES
     SELECT 'E200', COUNT(*) FROM (SELECT DISTINCT UF FROM EFD_E200 (:DATA1,:DATA2));

     DELETE FROM CONTADORES WHERE REG = 'E210';
     INSERT INTO CONTADORES SELECT 'E210', COUNT(*) FROM TB_ECFE210;

     DELETE FROM CONTADORES WHERE REG = 'E990';
     INSERT INTO CONTADORES (REG,QTDE) VALUES ('E990',1);

    BEGIN
    FOR
     SELECT
        'E990' AS REG,
        SUM(QTDE)
     FROM CONTADORES
     WHERE CONTADORES.REG IN ('E001','E100','E200','E210')
     INTO :REG, :VQTD_LIN_E

    DO

    QTD_LIN_E = :VQTD_LIN_E + 1;

    SUSPEND;
    END
END^


ALTER PROCEDURE EFD_G001
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    IND_MOV VARCHAR(1),
    FIM VARCHAR(1))
AS
BEGIN
    REG='G001';
    IND_MOV='1';
    SUSPEND;
END^


ALTER PROCEDURE EFD_G990
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    QTD_LIN_G INTEGER,
    FIM VARCHAR(1))
AS
declare variable VQTD_LIN_G integer;
BEGIN

    DELETE FROM CONTADORES WHERE REG = 'G001';
    INSERT INTO CONTADORES SELECT 'G001', COUNT(*) FROM EFD_G001;

    DELETE FROM CONTADORES WHERE REG = 'G990';
    INSERT INTO CONTADORES (REG, QTDE) VALUES ('G990',1);

    BEGIN
    FOR
     SELECT
        'G990' AS REG,
        SUM(QTDE)
     FROM CONTADORES
     WHERE CONTADORES.REG = 'G001'
     INTO :REG, :VQTD_LIN_G

    DO

    QTD_LIN_G = :VQTD_LIN_G + 1;

    SUSPEND;
    END
END^


ALTER PROCEDURE EFD_H001 (
    LOJA INTEGER,
    DATA_INV DATE)
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    IND_MOV VARCHAR(1),
    FIM VARCHAR(1))
AS
declare variable contador integer;
BEGIN
    REG = 'H001';

    SELECT COUNT(*) FROM EFD_H010 (:LOJA, :DATA_INV)
    INTO :CONTADOR;

    IF (CONTADOR > 1)
    THEN IND_MOV= '0';
    ELSE IND_MOV = '1';

    SUSPEND;
END^


ALTER PROCEDURE EFD_H005 (
    LOJA INTEGER,
    DATA_INV DATE)
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    DT_INV VARCHAR(8),
    VL_INV DOUBLE PRECISION,
    MOT_INV VARCHAR(2),
    FIM VARCHAR(1))
AS
declare variable vdt_inv timestamp;
BEGIN

    SELECT
       MAX(DATA)
    FROM INVENTARIO WHERE DATA <= CAST(:DATA_INV AS DATE) + 1
    AND LOJA = :LOJA
    INTO :VDT_INV;

    IF (VDT_INV IS NOT NULL)
    THEN
      BEGIN
         SELECT
            'H005',
            SUM(QUANTIDADE * VALORUNITARIO),
            '01'
          FROM INVENTARIO
          WHERE DATA = :VDT_INV
          AND LOJA = :LOJA
          INTO :REG, :VL_INV, :MOT_INV;

          DT_INV = SUBSTRING (CAST(:VDT_INV AS DATE) FROM 9 FOR 2) || SUBSTRING (CAST(:VDT_INV AS DATE) FROM 6 FOR 2) || SUBSTRING (CAST(:VDT_INV AS DATE) FROM 1 FOR 4);

          SUSPEND;
      END
END^


ALTER PROCEDURE EFD_H010 (
    LOJA INTEGER,
    DATA_INV DATE)
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    COD_ITEM INTEGER,
    UNID VARCHAR(6),
    QTD DOUBLE PRECISION,
    VL_UNIT DOUBLE PRECISION,
    VL_ITEM DOUBLE PRECISION,
    IND_PROP INTEGER,
    COD_PART VARCHAR(1),
    TXT_COMPL VARCHAR(1),
    COD_CTA VARCHAR(1),
    VL_ITEM_IR DOUBLE PRECISION,
    FIM VARCHAR(1),
    DT_INV TIMESTAMP)
AS
BEGIN
    REG = 'H010';
    IND_PROP = 0;
    COD_CTA = '1';
    COD_PART = '';
    VL_ITEM_IR = 0;

    SELECT
       MAX (DATA)
    FROM INVENTARIO WHERE DATA <= CAST(:DATA_INV AS DATE) + 1
    AND LOJA = :LOJA
    INTO :DT_INV;

    FOR
       SELECT
           CODPRODUTO,
           QUANTIDADE,
           VALORUNITARIO AS VL_UNIT
       FROM INVENTARIO WHERE LOJA = :LOJA
       AND DATA = :DT_INV
       INTO :COD_ITEM, :QTD, :VL_UNIT
       DO
        BEGIN
            VL_ITEM = (:VL_UNIT * :QTD);

            SELECT
                CODEMBALAGEM
            FROM PRODUTOS
            WHERE CODPRODUTO = :COD_ITEM
            INTO :UNID;

             SUSPEND;
        END
END^


ALTER PROCEDURE EFD_H990 (
    LOJA INTEGER,
    DATA_INV DATE)
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    QTD_LIN_H INTEGER,
    FIM VARCHAR(1))
AS
declare variable vqtd_lin_h integer;
BEGIN

    DELETE FROM CONTADORES WHERE REG = 'H001';
    INSERT INTO CONTADORES (REG, QTDE) VALUES ('H001',1);

    DELETE FROM CONTADORES WHERE REG = 'H005';
    INSERT INTO CONTADORES SELECT 'H005', COUNT(*) FROM EFD_H005 (:LOJA,:DATA_INV);

    DELETE FROM CONTADORES WHERE REG = 'H010';
    INSERT INTO CONTADORES SELECT 'H010', COUNT(*) FROM EFD_H010 (:LOJA,:DATA_INV);

    DELETE FROM CONTADORES WHERE REG = 'H990';
    INSERT INTO CONTADORES (REG, QTDE) VALUES ('H990',1);

   BEGIN
    FOR
     SELECT
        'H990' AS REG,
        SUM(QTDE)
     FROM CONTADORES
     WHERE CONTADORES.REG IN ('H001','H005','H010')
     INTO :REG, :VQTD_LIN_H
     DO
      QTD_LIN_H = :VQTD_LIN_H + 1;
      SUSPEND;
   END
END^


ALTER PROCEDURE EFD_PISCOFINS_0000 (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    COD_VER VARCHAR(4),
    TIPO_ESCRIT INTEGER,
    IND_SIT_ESP INTEGER,
    NUM_REC_ANTERIOR VARCHAR(10),
    DT_INI VARCHAR(8),
    DT_FIN VARCHAR(8),
    NOME VARCHAR(100),
    CNPJ VARCHAR(14),
    UF VARCHAR(2),
    COD_MUN VARCHAR(7),
    SUFRAMA VARCHAR(9),
    IND_NAT_PJ VARCHAR(2),
    IND_ATIV VARCHAR(1),
    FIM INTEGER)
AS
BEGIN

--- Deleta tabelas temporarias do SPED.
     DELETE FROM CONTADORES;
     DELETE FROM TB_ECFA170;
     DELETE FROM TB_ECFC110;
     DELETE FROM TB_ECFC120;
     DELETE FROM TB_ECFC140;
     DELETE FROM TB_ECFC141;
     DELETE FROM TB_ECFC170;
     DELETE FROM TB_ECFC190;
     DELETE FROM TB_ECFC195;
     DELETE FROM TB_ECFC197;
     DELETE FROM TB_ECFC405;
     DELETE FROM TB_ECFC420;
     DELETE FROM TB_ECFC460;
     DELETE FROM TB_ECFC470;
     DELETE FROM TB_ECFC481;
     DELETE FROM TB_ECFC485;
     DELETE FROM TB_ECFC490;
     DELETE FROM TB_ECFC490ECF;
     DELETE FROM TB_ECFC49X_ECF;
     DELETE FROM TB_ECFC491;
     DELETE FROM TB_ECFC495;
     DELETE FROM TB_ECFD110;
     DELETE FROM TB_ECFD190;
     DELETE FROM TB_ECFD201;
     DELETE FROM TB_ECFD205;
     DELETE FROM TB_ECFD590;
     DELETE FROM TB_ECFE210;
     DELETE FROM TB_ECFM410;
     DELETE FROM TB_ECFM810;
     DELETE FROM TB_ECFC100;
     DELETE FROM TB_ECFC100COMPRAS;
     DELETE FROM TB_ECFC100VENDAS;

     REG = '0000';
     COD_VER = '003';
     TIPO_ESCRIT = '0';
     IND_SIT_ESP = '0';
     NUM_REC_ANTERIOR = '';
     DT_INI = SUBSTRING (CAST(:DATA1 AS DATE) FROM 9 FOR 2) || SUBSTRING (CAST(:DATA1 AS DATE) FROM 6 FOR 2) || SUBSTRING (CAST(:DATA1 AS DATE) FROM 1 FOR 4);
     DT_FIN = SUBSTRING (CAST(:DATA2 AS DATE) FROM 9 FOR 2) || SUBSTRING (CAST(:DATA2 AS DATE) FROM 6 FOR 2) || SUBSTRING (CAST(:DATA2 AS DATE) FROM 1 FOR 4);
     IND_NAT_PJ = '00';
     IND_ATIV = '2';

--- Identificacao do Estabelecimento Matriz
     SELECT
       SUBSTRING (RAZAOSOCIAL FROM 1 FOR 99),
       CGC AS CNPJ,
       UF,
       CODCIDADEIBGE
     FROM EMPRESA
     WHERE CODLOJA = 1    --- Informar Cod.Loja do Estabelecimento Matriz
     INTO :NOME, :CNPJ, :UF, :COD_MUN;

 --------------------------------------------- GERA DADOS PARA TABELAS EFD

     INSERT INTO TB_ECFC100COMPRAS
       (LOJA, CODCOMPRA, STATUS, CNPJ, IE, DATA, UF, MODELO, CHV_NFE, SERIE, SUBSERIE, NUMERO,
       CFOP, EMITENTE, SITTRIB, SITTRIBIPI, NUMITEM, CODPRODUTO, QUANTIDADE, PRECOBRUTO,
       DESCONTO, OUTRASDESPESAS, VALORFRETEREAL, VALORTOTAL, BASEICMS, BASEICMSST,
       VALORICMS, VALORICMSST, ISENTAS, OUTRAS, ALIQUOTAICMS, VALORIPI,
       SITTRIBPIS, BASEPIS, ALIQUOTAPIS, VALORPIS,
       SITTRIBCOFINS, BASECOFINS, ALIQUOTACOFINS, VALORCOFINS,
       SITUACAO, CODANTECIPACAOTRIBUTARIA, MODALIDADEFRETE,
       NFSERVICOTRANSPORTE, CODIGONCM, DESCRICAO, CODEMBALAGEM, REDUCAOBASEICMS)
     SELECT
        LOJA, CODCOMPRA, STATUS, CNPJ, IE, DATA, UF, MODELO, CHV_NFE, SERIE, SUBSERIE, NUMERO,
        CFOP, EMITENTE, SITTRIB, SITTRIBIPI, NUMITEM,
        CODPRODUTO, QUANTIDADE,

         CASE
            WHEN (DESCONTO < 0) THEN PRECOBRUTO + DESCONTO
             ELSE PRECOBRUTO
         END AS VL_ITEM,

         CASE
            WHEN (DESCONTO < 0) THEN 0
            ELSE DESCONTO
         END AS VL_DESC,

       OUTRASDESPESAS, VALORFRETEREAL, VALORTOTAL, BASEICMS, BASEICMSST, VALORICMS,
       VALORICMSST, ISENTAS, OUTRAS, ALIQUOTAICMS, VALORIPI,
       SITTRIBPIS, BASEPIS, ALIQUOTAPIS, CAST (VALORPIS AS NUMERIC (15,2)),
       SITTRIBCOFINS, BASECOFINS, ALIQUOTACOFINS, CAST (VALORCOFINS AS NUMERIC (15,2)),
       SITUACAO, CODANTECIPACAOTRIBUTARIA, MODALIDADEFRETE, NFSERVICOTRANSPORTE,
       CODIGONCM, DESCRICAO, CODEMBALAGEM, REDUCAOBASEICMS
     FROM EFD_PISCOFINS_C100C (:DATA1, :DATA2)
     WHERE CODPRODUTO IS NOT NULL;
 -----
     INSERT INTO TB_ECFC100VENDAS
      (LOJA, CODORCAMENTO, STATUS, STATUSNFE, DATA, CNPJ, IE, UF, MODELO, CHV_NFE, SERIE,
       EMITENTE, NUMERO, CFOP, SITTRIB, SITTRIBIPI, SITTRIBCOFINS, NUMITEM, TIPOPRODUTO,
       CODPRODUTO, QUANTIDADE, PRECOBRUTO, DESCONTODESPESA, VALORTOTAL, BASEICMS,
       BASEICMSST, VALORICMS, VALORICMSST, ISENTAS, OUTRAS, BASEIPI, VALORIPI,
       SITTRIBPIS, BASEPIS, ALIQUOTAPIS, VALORPIS, BASECOFINS, ALIQUOTACOFINS,
       VALORCOFINS, ALIQUOTAICMS, ALIQUOTAICMSST, ALIQUOTAIPI, SITUACAO, CODIGONCM,
       DESCRICAO, CODEMBALAGEM, OUTRASDESPESAS, REDUCAOBASEICMS, CUPOMFISCAL)
    SELECT
       LOJA, CODORCAMENTO, STATUS, STATUSNFE, DATA, CNPJ, IE, UF, MODELO, CHV_NFE, SERIE,
       EMITENTE, NUMERO, CFOP, SITTRIB, SITTRIBIPI, SITTRIBCOFINS, NUMITEM, TIPOPRODUTO,
       CODPRODUTO, QUANTIDADE, PRECOBRUTO, DESCONTODESPESA, VALORTOTAL,
       BASEICMS, BASEICMSST, VALORICMS, VALORICMSST, ISENTAS, OUTRAS, BASEIPI,
       VALORIPI, SITTRIBPIS, BASEPIS, ALIQUOTAPIS, CAST (VALORPIS AS NUMERIC (15,2)),
       BASECOFINS, ALIQUOTACOFINS, CAST (VALORCOFINS AS NUMERIC (15,2)),
       ALIQUOTAICMS, ALIQUOTAICMSST, ALIQUOTAIPI, SITUACAO, CODIGONCM, DESCRICAO,
       CODEMBALAGEM, OUTRASDESPESAS, REDUCAOBASEICMS, CUPOMFISCAL
    FROM EFD_PISCOFINS_C100V (:DATA1, :DATA2)
    WHERE CODPRODUTO IS NOT NULL;
 -----
     INSERT INTO TB_ECFC100VENDAS
      (LOJA, CODORCAMENTO, STATUS, STATUSNFE, DATA, CNPJ, IE, UF, MODELO, CHV_NFE, SERIE,
       EMITENTE, NUMERO, CFOP, SITTRIB, SITTRIBIPI, SITTRIBCOFINS, NUMITEM, TIPOPRODUTO,
       CODPRODUTO, QUANTIDADE, PRECOBRUTO, DESCONTODESPESA, VALORTOTAL, BASEICMS,
       BASEICMSST, VALORICMS, VALORICMSST, ISENTAS, OUTRAS, BASEIPI, VALORIPI,
       SITTRIBPIS, BASEPIS, ALIQUOTAPIS, VALORPIS, BASECOFINS, ALIQUOTACOFINS,
       VALORCOFINS, ALIQUOTAICMS, ALIQUOTAICMSST, ALIQUOTAIPI, SITUACAO, CODIGONCM,
       DESCRICAO, CODEMBALAGEM, OUTRASDESPESAS, REDUCAOBASEICMS, CUPOMFISCAL)
    SELECT
       LOJA, CODORCAMENTO, STATUS, STATUSNFE, DATA, CNPJ, IE, UF, MODELO, CHV_NFE, SERIE,
       EMITENTE, NUMERO, CFOP, SITTRIB, SITTRIBIPI, SITTRIBCOFINS, NUMITEM, TIPOPRODUTO,
       CODPRODUTO, QUANTIDADE, PRECOBRUTO, DESCONTODESPESA, VALORTOTAL,
       BASEICMS, BASEICMSST, VALORICMS, VALORICMSST, ISENTAS, OUTRAS, BASEIPI,
       VALORIPI, SITTRIBPIS, BASEPIS, ALIQUOTAPIS, CAST (VALORPIS AS NUMERIC (15,2)),
       BASECOFINS, ALIQUOTACOFINS, CAST (VALORCOFINS AS NUMERIC (15,2)),
       ALIQUOTAICMS, ALIQUOTAICMSST, ALIQUOTAIPI, SITUACAO, CODIGONCM, DESCRICAO,
       CODEMBALAGEM, OUTRASDESPESAS, REDUCAOBASEICMS, CUPOMFISCAL
    FROM EFD_PISCOFINS_C100VS (:DATA1, :DATA2)
    WHERE CODPRODUTO IS NOT NULL;
 -----
     INSERT INTO TB_ECFC100
        (INI, REG, IND_OPER, IND_EMIT, COD_PART, COD_MOD, COD_SIT, SER, NUM_DOC,
         CHV_NFE, DT_DOC, DT_E_S, VL_DOC, IND_PGTO, VL_DESC, VL_ABAT_NT, VL_MERC,
         IND_FRT, VL_FRT, VL_SEG, VL_OUT_DA, VL_BC_ICMS, VL_ICMS, VL_BC_ICMS_ST,
         VL_ICMS_ST, VL_IPI, VL_PIS, VL_COFINS, VL_PIS_ST, VL_COFINS_ST, CODIGO,
         TIPO, FIM, LOJAP)
      SELECT
         INI, REG, IND_OPER, IND_EMIT, COD_PART, COD_MOD, COD_SIT, SER, NUM_DOC,
         CHV_NFE, DT_DOC, DT_E_S, VL_DOC, IND_PGTO, VL_DESC, VL_ABAT_NT, VL_MERC,
         IND_FRT, VL_FRT, VL_SEG, VL_OUT_DA, VL_BC_ICMS, VL_ICMS, VL_BC_ICMS_ST,
         VL_ICMS_ST, VL_IPI, VL_PIS, VL_COFINS, VL_PIS_ST, VL_COFINS_ST, CODIGO,
         TIPO, FIM, LOJAP
      FROM EFD_PISCOFINS_C100;
 -----
     INSERT INTO TB_ECFC49X_ECF     -- Apuracao PIS-PASEP / COFINS
       (LOJA, CODORCAMENTO, STATUS, DATA, NUMSERIEECF, MODELO, CUPOMFISCAL, NUMITEM,
       CODPRODUTO, QUANTIDADE, VALORLIQUIDO, BASEPIS, VALORPIS, SITTRIBPIS, ALIQ_PIS,
       BASECOFINS, VALORCOFINS, SITTRIBCOFINS, ALIQ_COFINS, CFOP)
     SELECT
       LOJA, CODORCAMENTO, STATUS, DATA, NUMSERIEECF, MODELO, CUPOMFISCAL, NUMITEM,
       CODPRODUTO, QUANTIDADE,
       CAST (VALORLIQUIDO AS NUMERIC (15,2)),
       CAST (BASEPIS AS NUMERIC (15,2)), CAST (VALORPIS AS NUMERIC (15,2)), SITTRIBPIS, ALIQ_PIS,
       CAST (BASECOFINS AS NUMERIC (15,2)), CAST (VALORCOFINS AS NUMERIC (15,2)), SITTRIBCOFINS, ALIQ_COFINS,
       CFOP
     FROM EFD_PISCOFINS_C49X_ECF (:DATA1, :DATA2);

     SUSPEND;

END^


