RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    IND_MOV VARCHAR(1),
    FIM VARCHAR(1))
AS
BEGIN
    REG = '0001';
    IND_MOV = '0';
  SUSPEND;
