ALTER PROCEDURE EFD_PISCOFINS_0100
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    NOME VARCHAR(60),
    CPF VARCHAR(15),
    CRC VARCHAR(15),
    CNPJ VARCHAR(14),
    CEP VARCHAR(8),
    ENDERECO VARCHAR(60),
    NUM VARCHAR(10),
    COMPL VARCHAR(10),
    BAIRRO VARCHAR(50),
    FONE VARCHAR(20),
    FAX VARCHAR(15),
    EMAIL VARCHAR(100),
    COD_MUN VARCHAR(10),
    FIM VARCHAR(10))
AS
BEGIN
REG = '0100';

SELECT
   CGCCONTADOR
FROM EMPRESA
WHERE CODLOJA = 1   --- Informar Cod.Loja do Estabelecimento Matriz
INTO :CPF;

SELECT
    RAZAOSOCIAL,
    CNPJMATRIZ,
    INSCESTADUAL,
    CEP,
    ENDERECO,
    '' AS NUM,
    '' AS COMPL,
    BAIRRO,
    DDD||FONE,
    FAX,
    EMAIL,
    CODCIDADEIBGE
FROM CLIENTES
WHERE CGC = :CPF
INTO :NOME, :CNPJ,:CRC, :CEP, :ENDERECO, :NUM, :COMPL, :BAIRRO, :FONE,:FAX, :EMAIL, COD_MUN;

SUSPEND;
END^


ALTER PROCEDURE EFD_PISCOFINS_0110
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    COD_INC_TRIB VARCHAR(1),
    IND_APRO_CRED VARCHAR(1),
    COD_TIPO_CONT VARCHAR(1),
    IND_REG_CUM VARCHAR(1),
    FIM VARCHAR(1))
AS
BEGIN
  FOR
   SELECT
     '0110' AS REG,

     SPEDCODINCTRIB AS COD_IND_TRIB,
     -- 1 Nao Cumulativo /  2 Cumulativo  /  3 Ambos
     -- (Lucro Real) / (Lucro Presumido)  /  (Ambos)

     '1' AS IND_APRO_CRED,  -- Se COD_IND_TRIB = 3 entao '2'. Se nao entao '1'
     '1' AS COD_TIPO_CONT,  -- Se COD_IND_TRIB = 3 entao '2'. Se nao entao '1'

     ' ' AS IND_REG_CUM -- Preencher 2 quando Regime Cumulativo
                        -- Inativar campo quando for Regime Nao-Cumulativo
   FROM EMPRESA
   WHERE CODLOJA = 1 --- Informar Cod.Loja do Estabelecimento Matriz
   INTO REG, COD_INC_TRIB, IND_APRO_CRED, COD_TIPO_CONT, IND_REG_CUM
   DO
    SUSPEND;
END^


ALTER PROCEDURE EFD_PISCOFINS_0140
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    COD_EST INTEGER,
    NOME VARCHAR(100),
    CNPJ VARCHAR(14),
    UF VARCHAR(2),
    IE VARCHAR(14),
    COD_MUN VARCHAR(7),
    IM VARCHAR(15),
    SUFRAMA VARCHAR(9),
    FIM INTEGER,
    LOJAP INTEGER)
AS
BEGIN
  REG = '0140';
   FOR
     SELECT                    -- VENDAS
        E.CODLOJA,
        SUBSTRING (E.RAZAOSOCIAL FROM 1 FOR 99),
        E.CGC AS CNPJ,
        E.UF,
        SUBSTRING (E.IE FROM 1 FOR 14),
        E.CODCIDADEIBGE,
        E.IM
     FROM EMPRESA E
     JOIN TB_ECFC100VENDAS V ON (E.CODLOJA = V.LOJA)

    UNION

     SELECT       -- CUPONS
        E.CODLOJA,
        SUBSTRING (E.RAZAOSOCIAL FROM 1 FOR 99),
        E.CGC AS CNPJ,
        E.UF,
        SUBSTRING (E.IE FROM 1 FOR 14),
        E.CODCIDADEIBGE,
        E.IM
     FROM EMPRESA E
     JOIN TB_ECFC49X_ECF CF ON (E.CODLOJA = CF.LOJA)

    UNION

     SELECT  -- COMPRAS
        E.CODLOJA,
        SUBSTRING (E.RAZAOSOCIAL FROM 1 FOR 99),
        E.CGC AS CNPJ,
        E.UF,
        SUBSTRING (E.IE FROM 1 FOR 14),
        E.CODCIDADEIBGE,
        E.IM
     FROM EMPRESA E
     JOIN TB_ECFC100COMPRAS C ON (E.CODLOJA = C.LOJA)


     INTO :COD_EST, :NOME, :CNPJ, :UF, :IE, :COD_MUN, :IM
   DO
    BEGIN
       LOJAP = :COD_EST;
       SUSPEND;
     END
END^


ALTER PROCEDURE EFD_PISCOFINS_0150
RETURNS (
    INI INTEGER,
    REG VARCHAR(4),
    COD_PART VARCHAR(60),
    NOME VARCHAR(100),
    COD_PAIS VARCHAR(5),
    CNPJ VARCHAR(14),
    CPF VARCHAR(11),
    IE VARCHAR(14),
    COD_MUN VARCHAR(7),
    SUFRAMA VARCHAR(9),
    ENDERECO VARCHAR(60),
    NUM VARCHAR(10),
    COMPL VARCHAR(60),
    BAIRRO VARCHAR(60),
    FIM INTEGER,
    LOJA INTEGER)
AS
declare variable vcnpj varchar(14);
BEGIN
---------------------------- CADASTRO DE PARTICIPANTES
    REG = '0150';
    CNPJ = NULL;
-------------------------------------------------------------------- CLIENTES
    FOR SELECT
          A.LOJA,
          A.CNPJ
        FROM TB_ECFC100VENDAS A
        WHERE EXISTS (SELECT * FROM CLIENTES C WHERE C.CGC = A.CNPJ)
        AND STATUS NOT IN (9,10,12,15)
        AND A.CNPJ IS NOT NULL
        GROUP BY 1,2 ORDER BY 1
        INTO LOJA, :VCNPJ

    DO BEGIN

       SELECT
           SUBSTRING (CGC FROM 1 FOR 60) AS COD_PART,

           SUBSTRING (RAZAOSOCIAL FROM 1 FOR 60),

           COALESCE (CODPAIS, '1058') AS COD_PAIS,

           CASE
             WHEN (SUBSTRING (CODCIDADEIBGE FROM 1 FOR 60) = '9999999' OR COALESCE (CODPAIS, '1058') <> '1058') THEN ''
             WHEN (SUBSTRING(CGC FROM 12 FOR 13) <> '') THEN CGC
             ELSE ''
           END AS CNPJ,

           CASE
             WHEN (SUBSTRING (CODCIDADEIBGE FROM 1 FOR 60) = '9999999' OR COALESCE (CODPAIS, '1058')  <> '1058') THEN ''
             WHEN (SUBSTRING (CGC FROM 12 FOR 13) = '') THEN CGC
           ELSE '' END AS CPF,

           CASE
             WHEN (INSCESTADUAL LIKE '%ISENTO%' OR SUBSTRING (CGC FROM 12 FOR 13) = '') THEN ''
             ELSE SUBSTRING (INSCESTADUAL FROM 1 FOR 14)
           END,

           CASE
              WHEN (CODCIDADEIBGE IS NULL AND UF = 'DF') THEN '5300108'
              ELSE SUBSTRING (CODCIDADEIBGE FROM 1 FOR 60)
           END,

           SUBSTRING (ENDERECO FROM 1 FOR 60),

           '' AS NUMERO,

           '' AS COMPLEMENTO,

           SUBSTRING(BAIRRO FROM 1 FOR 60)

       FROM CLIENTES WHERE CGC = :VCNPJ
       INTO :COD_PART, :NOME, :COD_PAIS, :CNPJ, :CPF, :IE, :COD_MUN, :ENDERECO, :NUM,
            :COMPL, :BAIRRO;

       SUSPEND;
       END
------------------------------------------------------------------ FORNECEDORES
    FOR SELECT
           A.LOJA,
           A.CNPJ
        FROM TB_ECFC100COMPRAS A
        WHERE NOT EXISTS (SELECT * FROM TB_ECFC100VENDAS C WHERE C.CNPJ = A.CNPJ)
        AND A.CNPJ IS NOT NULL
        GROUP BY 1,2 ORDER BY 1
        INTO :LOJA, :VCNPJ

    DO BEGIN
       SELECT FIRST 1

              SUBSTRING(CGC FROM 1 FOR 60) AS COD_PART,

              SUBSTRING(RAZAOSOCIAL FROM 1 FOR 60),

              CASE
                WHEN ( SUBSTRING (CODCIDADEIBGE FROM 1 FOR 60) = '9999999' OR UF = 'EX' )
                 THEN '2496' --- Padrao EUA (Tabela Fornecedores nao tem COD_PAIS)
                ELSE '1058'
              END AS COD_PAIS,

              CASE
                WHEN (SUBSTRING (CODCIDADEIBGE FROM 1 FOR 60) <> '9999999' AND UF <> 'EX' AND SUBSTRING (CGC FROM 12 FOR 13) <> '' ) THEN CGC -- Pessoas Nacionais
                WHEN (SUBSTRING (CODCIDADEIBGE FROM 1 FOR 60) =  '9999999' OR UF = 'EX') THEN ''   -- Pessoas Extrangeiras
                ELSE ''
              END AS CNPJ,

              CASE
                WHEN (SUBSTRING (CODCIDADEIBGE FROM 1 FOR 60) <> '9999999' AND UF <> 'EX' AND SUBSTRING (CGC FROM 12 FOR 13) = '') THEN CGC  -- Pessoas Nacionais
                WHEN (SUBSTRING (CODCIDADEIBGE FROM 1 FOR 60) = '9999999' OR UF = 'EX') THEN ''    -- Pessoas Extrangeiras
                ELSE ''
              END AS CPF,

              CASE
               WHEN (IE LIKE '%ISENTO%' OR SUBSTRING (CGC FROM 12 FOR 13) = '') THEN ''
                ELSE SUBSTRING(IE FROM 1 FOR 14)
              END,

              CASE
                 WHEN (CODCIDADEIBGE IS NULL AND UF = 'DF') THEN '5300108'
                 ELSE SUBSTRING (CODCIDADEIBGE FROM 1 FOR 60)
              END AS CODMUNICIPIOIBGE,

              SUBSTRING (ENDERECO FROM 1 FOR 60),

              '' AS NUMERO,

              '' AS COMPLEMENTO,

              SUBSTRING(BAIRRO FROM 1 FOR 60)

       FROM FORNECEDORES WHERE CGC = :VCNPJ
       INTO :COD_PART, :NOME, :COD_PAIS, :CNPJ, :CPF, :IE, :COD_MUN, :ENDERECO, :NUM, :COMPL, :BAIRRO;

       SUSPEND;
       END

END^


ALTER PROCEDURE EFD_PISCOFINS_0190
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    UNID VARCHAR(6),
    DESCR VARCHAR(60),
    FIM VARCHAR(1),
    LOJA INTEGER)
AS
BEGIN ----------------------------------------- CADASTRO DE EMBALAGENS
     REG = '0190';
     FOR
         SELECT
            LOJA,
            SUBSTRING(CODEMBALAGEM FROM 1 FOR 6)   -- VENDAS
         FROM TB_ECFC100VENDAS
         WHERE NUMITEM NOT IN (991,999)
         AND SUBSTRING (COALESCE(MODELO,0) FROM 1 FOR 2) IN ('01','1B','04','55')
       --  AND (SUBSTRING(COALESCE(MODELO,0) FROM 1 FOR 2) IN ('01','1B','04') or (STATUS = 3 AND EMITENTE = 'T'))

        UNION

         SELECT
            LOJA,
            SUBSTRING(CODEMBALAGEM FROM 1 FOR 6)      -- CUPONS
         FROM PRODUTOS P
         JOIN TB_ECFC49X_ECF A ON (P.CODPRODUTO = A.CODPRODUTO)

       UNION

         SELECT
            LOJA,
            SUBSTRING (P.CODEMBALAGEM FROM 1 FOR 6) -- COMPRAS
         FROM PRODUTOS P
         JOIN TB_ECFC100COMPRAS A ON (P.CODPRODUTO = A.CODPRODUTO)
         WHERE NUMITEM NOT IN (991,999)
         AND SUBSTRING (COALESCE(MODELO,0) FROM 1 FOR 2) IN ('01','1B','04','55')
         INTO :LOJA, :UNID

     DO
      BEGIN

        SELECT FIRST 1
          SUBSTRING (E.EMBALAGEM FROM 1 FOR 60)
        FROM EMBALAGEM E
        WHERE CODEMBALAGEM = :UNID
        INTO :DESCR;

       SUSPEND;

      END
END^


ALTER PROCEDURE EFD_PISCOFINS_0200
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    COD_ITEM VARCHAR(50),
    DESCR_ITEM VARCHAR(200),
    COD_BARRA VARCHAR(30),
    COD_ANT_ITEM INTEGER,
    UNID_INV VARCHAR(6),
    TIPO_ITEM VARCHAR(2),
    COD_NCM VARCHAR(8),
    EX_IPI VARCHAR(3),
    COD_GEN VARCHAR(2),
    COD_LST VARCHAR(4),
    ALIQ_ICMS DOUBLE PRECISION,
    FIM VARCHAR(1),
    LOJA INTEGER)
AS
BEGIN
------------------------------------ CADASTRO DE PRODUTOS
     REG = '0200';
     FOR
         SELECT
            LOJA,
            CODPRODUTO        -- VENDAS
         FROM TB_ECFC100VENDAS
         WHERE NUMITEM NOT IN (991,999)
         AND CODPRODUTO NOT LIKE 'S%'

         UNION

         SELECT
            LOJA,
            CODPRODUTO        -- CUPONS
         FROM TB_ECFC49X_ECF
         WHERE CODPRODUTO NOT LIKE 'S%'

         UNION

         SELECT
             LOJA,
             CODPRODUTO      -- COMPRAS
         FROM TB_ECFC100COMPRAS
         WHERE NUMITEM NOT IN (991,999)
         AND CODPRODUTO NOT LIKE 'S%'
         INTO :LOJA, :COD_ITEM

     DO
       BEGIN
          SELECT
             P.DESCRICAO,
             P.CODBARRAS,
             P.CODEMBALAGEM AS NID_INV,
             '00' AS TIPO_ITEM,

             CASE
                WHEN P.SITTRIB = '0S0' THEN ' '
                ELSE SUBSTRING (P.NBM FROM 1 FOR 8)
              END AS COD_NCM,

             P.ICMS AS ALIQ_ICMS
          FROM PRODUTOS P
          WHERE P.CODPRODUTO = :COD_ITEM
          INTO :DESCR_ITEM, :COD_BARRA, :UNID_INV, :TIPO_ITEM, :COD_NCM, :ALIQ_ICMS;

           SUSPEND;
        END

------------------------------------ CADASTRO DE SERVICOS
     FOR
         SELECT
            LOJA,
            CODPRODUTO        -- VENDAS
         FROM TB_ECFC100VENDAS
         WHERE NUMITEM NOT IN (991,999)
         AND CODPRODUTO LIKE 'S%'

         UNION

         SELECT
            LOJA,
            CODPRODUTO        -- CUPONS
         FROM TB_ECFC49X_ECF --- TABELA VENDAS CUPONS
         WHERE STATUS <> 9
         AND CODPRODUTO LIKE 'S%'
         GROUP BY 1,2
         ORDER BY 1
         INTO LOJA, :COD_ITEM

     DO BEGIN
          SELECT
              DESCRICAO,
              '0',
              CODEMBALAGEM AS NID_INV,
              '00' AS TIPO_ITEM,
              ' ',
              '0'
          FROM SERVICOS S
          WHERE CODSERVICO = SUBSTRING (:COD_ITEM FROM 2 FOR 10)
          INTO :DESCR_ITEM, :COD_BARRA, :UNID_INV, :TIPO_ITEM, :COD_NCM, :ALIQ_ICMS;

        SUSPEND;
        END

END^


ALTER PROCEDURE EFD_PISCOFINS_0400
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    COD_NAT VARCHAR(4),
    DESCR_NAT VARCHAR(250),
    FIM VARCHAR(1),
    LOJA INTEGER)
AS
BEGIN ----------------TABELA DE NATUREZA DA OPERACAO/PRESTACAO
     REG = '0400';
     FOR
         SELECT     ---- VENDAS
            V.LOJA,
            V.CFOP
         FROM TB_ECFC100VENDAS V
         WHERE V.NUMITEM NOT IN (991,999)
         AND SUBSTRING(COALESCE(V.MODELO,0) FROM 1 FOR 2) IN ('01','1B','04','55')

        UNION

         SELECT     ---- COMPRAS
            A.LOJA,
            A.CFOP
         FROM PRODUTOS P
         JOIN TB_ECFC100COMPRAS A ON (P.CODPRODUTO = A.CODPRODUTO)
         WHERE A.NUMITEM NOT IN (991,999)
         AND SUBSTRING(COALESCE(A.MODELO,0) FROM 1 FOR 2) IN ('01','1B','04','55')
         GROUP BY 1,2
         ORDER BY 1
         INTO :LOJA, :COD_NAT

     DO
      BEGIN

        SELECT FIRST 1
           SUBSTRING (NATUREZAOPERACAO FROM 1 FOR 60)
        FROM CFOP
        WHERE CFOPN = :COD_NAT
        INTO :DESCR_NAT;
         SUSPEND;

      END
END^


ALTER PROCEDURE EFD_PISCOFINS_0450 (
    LOJA1 INTEGER)
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    COD_INF INTEGER,
    TXT VARCHAR(100),
    FIN VARCHAR(1))
AS
BEGIN ------------------------------------ CADASTRO DE OBSERVACOES

  FOR
     SELECT
        '0450' AS REG,
        C.CODCOMPRA AS COD_INF,
        C1.OBS AS TXT
      FROM TB_ECFC100COMPRAS C
      JOIN COMPRAS C1 ON (C1.CODCOMPRA = C.CODCOMPRA AND C1.LOJA = C.LOJA)
      AND C.LOJA = :LOJA1
      AND COALESCE(C1.OBS, '') <> ''
      GROUP BY 1,2,3
      INTO :REG, :COD_INF, :TXT
  DO
     SUSPEND;
END^


ALTER PROCEDURE EFD_PISCOFINS_0500
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    DT_ALT VARCHAR(8),
    COD_NAT_CC VARCHAR(2),
    IND_CTA VARCHAR(1),
    NIVEL VARCHAR(5),
    COD_CTA VARCHAR(60),
    NOME_CTA VARCHAR(60),
    COD_CTA_REF VARCHAR(60),
    CNPJ_EST VARCHAR(14),
    FIM VARCHAR(1))
AS
declare variable prazomedio double precision;
declare variable v_codcompra integer;
BEGIN
  REG = '0500';

  BEGIN
 FOR
     SELECT
         SUBSTRING(CAST('NOW' AS DATE) FROM 9 FOR 2) || SUBSTRING(CAST('NOW' AS DATE) FROM 6 FOR 2) || SUBSTRING(CAST('NOW' AS DATE) FROM 1 FOR 4) AS DT_ALT,
         '01' AS COD_NAT_CC, --- CONTAS DE ATIVO
         'S' AS IND_CTA,
         '00001' AS NIVEL,
         '100' AS COD_CTA,
         'REVENDAS DE MERCADORIAS NO MERCADO INTERNO' AS NOME_CTA,
         '3.01.01.01.01.03.00' AS COD_CTA_REF,
         '' as CNPJ_EST
     FROM EMPRESA E
     GROUP BY 1
     INTO :DT_ALT, :COD_NAT_CC, :IND_CTA, :NIVEL, :COD_CTA, :NOME_CTA, :COD_CTA_REF, :CNPJ_EST
  DO
     BEGIN
       SUSPEND;
     END

   END

 FOR
     SELECT
         SUBSTRING(CAST('NOW' AS DATE) FROM 9 FOR 2) || SUBSTRING(CAST('NOW' AS DATE) FROM 6 FOR 2) || SUBSTRING(CAST('NOW' AS DATE) FROM 1 FOR 4) AS DT_ALT,
         '02' AS COD_NAT_CC, --- CONTAS DE PASSIVO
         'S' AS IND_CTA,
         '00001' AS NIVEL,
         '101' AS COD_CTA,
         'COMPRAS DE MERCADORIAS A PRAZO' AS NOME_CTA,
         '3.01.01.03.03.03.00' AS COD_CTA_REF,
         '' as CNPJ_EST
     FROM EMPRESA E
     GROUP BY 1
     INTO :DT_ALT, :COD_NAT_CC, :IND_CTA, :NIVEL, :COD_CTA, :NOME_CTA, :COD_CTA_REF, :CNPJ_EST
     DO
     BEGIN
       SUSPEND;
     END
END^


ALTER PROCEDURE EFD_PISCOFINS_0990
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    QTD_LIN_0 INTEGER,
    FIM VARCHAR(1))
AS
declare variable vqtd_lin_0 integer;
BEGIN
     DELETE FROM CONTADORES WHERE REG = '0000';
     INSERT INTO CONTADORES VALUES ('0000', 1);

     DELETE FROM CONTADORES WHERE REG = '0001';
     INSERT INTO CONTADORES VALUES ('0001', 1);

     DELETE FROM CONTADORES WHERE REG = '0100';
     INSERT INTO CONTADORES VALUES ('0100', 1);

     DELETE FROM CONTADORES WHERE REG = '0110';
     INSERT INTO CONTADORES VALUES ('0110', 1);

     DELETE FROM CONTADORES WHERE REG = '0140';
     INSERT INTO CONTADORES SELECT '0140', COUNT(*) FROM EFD_PISCOFINS_0140;

     DELETE FROM CONTADORES WHERE REG = '0150';
     INSERT INTO CONTADORES SELECT '0150', COUNT(*) FROM EFD_PISCOFINS_0150;

     DELETE FROM CONTADORES WHERE REG = '0190';
     INSERT INTO CONTADORES SELECT '0190', COUNT(*) FROM EFD_PISCOFINS_0190;

     DELETE FROM CONTADORES WHERE REG = '0200';
     INSERT INTO CONTADORES SELECT '0200', COUNT(*) FROM EFD_PISCOFINS_0200;

     DELETE FROM CONTADORES WHERE REG = '0400';
     INSERT INTO CONTADORES SELECT '0400', COUNT(*) FROM EFD_PISCOFINS_0400;

     DELETE FROM CONTADORES WHERE REG = '0500';
     INSERT INTO CONTADORES SELECT '0500', COUNT(*) FROM EFD_PISCOFINS_0500;

     DELETE FROM CONTADORES WHERE REG = '0990';
     INSERT INTO CONTADORES (REG, QTDE) VALUES ('0990', 1);


    BEGIN
    FOR
     SELECT
        '0990' AS REG, 
        SUM (QTDE)
     FROM CONTADORES
     WHERE CONTADORES.REG IN ('0000','0001','0100','0110','0140','0150','0190','0200','0400','0500','0990')
     INTO :REG, :VQTD_LIN_0

    DO

     QTD_LIN_0 = :VQTD_LIN_0 ;

     SUSPEND;
    END
END^


ALTER PROCEDURE EFD_PISCOFINS_1001
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    IND_MOV VARCHAR(1),
    FIM VARCHAR(1))
AS
BEGIN
    REG='1001';
    IND_MOV='1';
    SUSPEND;
END^


ALTER PROCEDURE EFD_PISCOFINS_1990
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    QTD_LIN_1 INTEGER,
    FIM VARCHAR(1))
AS
declare variable vqtd_lin_1 integer;
BEGIN

     DELETE FROM CONTADORES WHERE REG = '1001';
     INSERT INTO CONTADORES SELECT '1001', COUNT (*) FROM EFD_PISCOFINS_1001;

     DELETE FROM CONTADORES WHERE REG = '1990';
     INSERT INTO CONTADORES (REG, QTDE) VALUES ('1990',1);

BEGIN
    FOR
     SELECT
        '1990' AS REG,
        SUM (QTDE)
     FROM CONTADORES
     WHERE CONTADORES.REG = '1001'
     INTO :REG, :VQTD_LIN_1

    DO
      QTD_LIN_1 = :VQTD_LIN_1 + 1;
     SUSPEND;
    END
END^


ALTER PROCEDURE EFD_PISCOFINS_9001
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    IND_MOV VARCHAR(1),
    FIM VARCHAR(1))
AS
BEGIN
    REG='9001';
    IND_MOV='0';
  SUSPEND;
END^


ALTER PROCEDURE EFD_PISCOFINS_9900
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(5),
    REG_BLC VARCHAR(4),
    QTD_REG_BLC INTEGER,
    FIM VARCHAR(1))
AS
BEGIN
    BEGIN

        DELETE FROM CONTADORES WHERE REG = '9001';
        INSERT INTO CONTADORES (REG, QTDE) VALUES ('9001', 1);

        DELETE FROM CONTADORES WHERE REG = '9990';
        INSERT INTO CONTADORES (REG, QTDE) VALUES('9990', 1);

        DELETE FROM CONTADORES WHERE REG = '9999';
        INSERT INTO CONTADORES (REG, QTDE) VALUES('9999', 1);

        DELETE FROM CONTADORES WHERE REG = '9900';
        INSERT INTO CONTADORES SELECT '9900', COUNT(*) + 1 FROM CONTADORES;

        FOR
        SELECT
            '9900' AS REG,
            C.REG AS REG_BLC,
            SUM (C.QTDE) AS QTD_REG_BLC
        FROM CONTADORES C
        GROUP BY 1,2
        INTO :REG, :REG_BLC, :QTD_REG_BLC
        DO
        SUSPEND;
    END

END^


ALTER PROCEDURE EFD_PISCOFINS_9990
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    QTD_LIN_9 INTEGER,
    FIM VARCHAR(1))
AS
declare variable VREG varchar(4);
declare variable VQTD_LIN_9001 integer;
declare variable VQTD_LIN_9900 integer;
BEGIN

FOR
    SELECT
        '9990' AS REG,
        COUNT(*)
    FROM EFD_PISCOFINS_9001
    INTO :VREG, :VQTD_LIN_9001
DO

FOR
    SELECT
        '9990' AS REG,
        COUNT(*)
    FROM EFD_PISCOFINS_9900
    INTO :VREG, :VQTD_LIN_9900
DO

 REG = :VREG;

 QTD_LIN_9 = :VQTD_LIN_9001 + :VQTD_LIN_9900 + 2;


    SUSPEND;
END^


ALTER PROCEDURE EFD_PISCOFINS_9999
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    QTD_LIN INTEGER,
    FIM VARCHAR(1))
AS
declare variable VQTD_LIN integer;
BEGIN

     SELECT
        '9999',
        SUM (C.QTDE)
     FROM CONTADORES C
     GROUP BY 1            
     INTO :REG, :QTD_LIN;

    SUSPEND;
END^


