    COD_CTA VARCHAR(60),
    FIM VARCHAR(1))
AS
declare variable CONT integer;
BEGIN
 REG = 'C485';

 QUANT_BC_COFINS = NULL;
 ALIQ_COFINS_QUANT = NULL;

    FOR SELECT
            SITTRIBCOFINS,
            SUM (VALORLIQUIDO),
            SUM (BASECOFINS),
            ALIQ_COFINS,
            SUM (VALORCOFINS),
            CODPRODUTO,
