ALTER PROCEDURE EFD_PISCOFINS_D990
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    QTD_LIN_D INTEGER,
    FIM VARCHAR(1))
AS
declare variable vqtd_lin_d integer;
declare variable d100 integer;
BEGIN

     DELETE FROM CONTADORES WHERE REG = 'D001';
     INSERT INTO CONTADORES SELECT 'D001', COUNT(*) FROM EFD_PISCOFINS_D001;

     DELETE FROM CONTADORES WHERE REG = 'D010';
     INSERT INTO CONTADORES SELECT 'D010', COUNT(*) FROM EFD_PISCOFINS_D010;

     DELETE FROM CONTADORES WHERE REG = 'D100';
     INSERT INTO CONTADORES SELECT 'D100', COUNT(*) FROM EFD_PISCOFINS_D100(NULL);

     DELETE FROM CONTADORES WHERE REG = 'D190';
     INSERT INTO CONTADORES SELECT 'D190', COUNT(*) FROM TB_ECFD190;

     DELETE FROM CONTADORES WHERE REG = 'D110';
     INSERT INTO CONTADORES SELECT 'D110', COUNT(*) FROM TB_ECFD110;

     DELETE FROM CONTADORES WHERE REG = 'D200';
     INSERT INTO CONTADORES SELECT 'D200', COUNT(*) FROM EFD_PISCOFINS_D200;

     DELETE FROM CONTADORES WHERE REG = 'D201';
     INSERT INTO CONTADORES SELECT 'D201', COUNT(*) FROM TB_ECFD201;

     DELETE FROM CONTADORES WHERE REG = 'D205';
     INSERT INTO CONTADORES SELECT 'D205', COUNT(*) FROM TB_ECFD205;

     DELETE FROM CONTADORES WHERE REG = 'D990';
     INSERT INTO CONTADORES (REG,QTDE) VALUES ('D990',1);

   BEGIN
    FOR
     SELECT
        'D990' AS REG,
        SUM(QTDE)
     FROM CONTADORES
     WHERE CONTADORES.REG IN ('D001','D010','D100','D110','D190','D990','D200','D201','D205')
     INTO :REG, :VQTD_LIN_D

    DO
        QTD_LIN_D = :VQTD_LIN_D;
      SUSPEND;
   END
END^


