ALTER PROCEDURE EFD_PISCOFINS_F990
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    QTD_LIN_C INTEGER,
    FIM VARCHAR(1))
AS
declare variable VQTD_LIN_C integer;
BEGIN

    DELETE FROM CONTADORES WHERE REG = 'F001';
    INSERT INTO CONTADORES (REG, QTDE) VALUES ('F001', 1);

    DELETE FROM CONTADORES WHERE REG = 'F990';
    INSERT INTO CONTADORES (REG, QTDE) VALUES ('F990',1);

BEGIN
    FOR
     SELECT
        'F990' AS REG,
        SUM(QTDE)
     FROM CONTADORES
     WHERE CONTADORES.REG IN ('F001','F990')
     INTO :REG, :VQTD_LIN_C

    DO
--     QTD_LIN_C = :VQTD_LIN_C + 1;
     QTD_LIN_C = :VQTD_LIN_C;

    SUSPEND;
END
END^


