ALTER PROCEDURE EFD_PISCOFINS_M200
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    VL_TOT_CONT_NC_PER DOUBLE PRECISION,
    VL_TOT_CRED_DESC DOUBLE PRECISION,
    VL_TOT_CRED_DESC_ANT DOUBLE PRECISION,
    VL_TOT_CONT_NC_DEV DOUBLE PRECISION,
    VL_RET_NC DOUBLE PRECISION,
    VL_OUT_DED_NC DOUBLE PRECISION,
    VL_CONT_NC_REC DOUBLE PRECISION,
    VL_TOT_CONT_CUM_PER DOUBLE PRECISION,
    VL_RET_CUM DOUBLE PRECISION,
    VL_OUT_DED_CUM DOUBLE PRECISION,
    VL_CONT_CUM_REC DOUBLE PRECISION,
    VL_TOT_CONT_REC DOUBLE PRECISION,
    FIM VARCHAR(1))
AS
BEGIN
 INI = '';
 FIM = '';
 REG = 'M200';

  FOR
      SELECT
        SUM (0) VL_TOT_CONT_NC_PER,
        SUM (0) VL_TOT_CRED_DESC,
        SUM (0) VL_TOT_CRED_DESC_ANT,
        SUM (0) VL_TOT_CONT_NC_DEV,
        SUM (0) VL_RET_NC,
        SUM (0) VL_OUT_DED_NC,
        SUM (0) VL_CONT_NC_REC,
        SUM (CAST (VALORPIS AS NUMERIC (15,2))) VL_TOT_CONT_CUM_PER,   ---9
        SUM (0) VL_RET_CUM,
        SUM (0) VL_OUT_DED_CUM,
        SUM (0) VL_CONT_CUM_REC,
        SUM (CAST (VALORPIS AS NUMERIC (15,2))) VL_TOT_CONT_REC   ---13
      FROM TB_ECFC100VENDAS
      WHERE SUBSTRING(COALESCE(MODELO,0) FROM 1 FOR 2) IN ('01','1B','04','55')
      AND STATUS NOT IN (9,10,12,15)
      AND SITTRIBPIS IN ('01', '51', '02', '52', '31', '32')
      AND ALIQUOTAPIS > 0
      INTO :VL_TOT_CONT_NC_PER, :VL_TOT_CRED_DESC, :VL_TOT_CRED_DESC_ANT,
           :VL_TOT_CONT_NC_DEV, :VL_RET_NC, :VL_OUT_DED_NC, :VL_CONT_NC_REC,
           :VL_TOT_CONT_CUM_PER, :VL_RET_CUM, :VL_OUT_DED_CUM, :VL_CONT_CUM_REC,
           :VL_TOT_CONT_REC

   DO
     BEGIN
      VL_CONT_CUM_REC = :VL_TOT_CONT_CUM_PER - :VL_CONT_NC_REC;

      SUSPEND;
     END
END^


