ALTER PROCEDURE EFD_PISCOFINS_M990
RETURNS (
    INI VARCHAR(1),
    REG VARCHAR(4),
    QTD_LIN_C INTEGER,
    FIM VARCHAR(1))
AS
declare variable vqtd_lin_c integer;
BEGIN

    DELETE FROM CONTADORES WHERE REG = 'M001';
    INSERT INTO CONTADORES (REG, QTDE) VALUES ('M001', 1);

    DELETE FROM CONTADORES WHERE REG = 'M200';
    INSERT INTO CONTADORES (REG, QTDE) SELECT 'M200', COUNT (*) FROM EFD_PISCOFINS_M200;

    DELETE FROM CONTADORES WHERE REG = 'M210';
    INSERT INTO CONTADORES (REG, QTDE) SELECT 'M210', COUNT (*) FROM EFD_PISCOFINS_M210;

    DELETE FROM CONTADORES WHERE REG = 'M400';
    INSERT INTO CONTADORES (REG, QTDE) SELECT 'M400', COUNT (*) FROM EFD_PISCOFINS_M400;

    DELETE FROM CONTADORES WHERE REG = 'M410';
    INSERT INTO CONTADORES (REG, QTDE) SELECT 'M410', COUNT (*) FROM TB_ECFM410;

    DELETE FROM CONTADORES WHERE REG = 'M600';
    INSERT INTO CONTADORES (REG, QTDE) SELECT 'M600', COUNT (*) FROM EFD_PISCOFINS_M600;

    DELETE FROM CONTADORES WHERE REG = 'M610';
    INSERT INTO CONTADORES (REG, QTDE) SELECT 'M610', COUNT (*) FROM EFD_PISCOFINS_M610;

    DELETE FROM CONTADORES WHERE REG = 'M800';
    INSERT INTO CONTADORES (REG, QTDE) SELECT 'M800', COUNT (*) FROM EFD_PISCOFINS_M800;

    DELETE FROM CONTADORES WHERE REG = 'M810';
    INSERT INTO CONTADORES (REG, QTDE) SELECT 'M810', COUNT (*) FROM TB_ECFM810;

    DELETE FROM CONTADORES WHERE REG = 'M990';
    INSERT INTO CONTADORES (REG, QTDE) VALUES ('M990',1);

  BEGIN
     FOR
      SELECT
         'M990' AS REG,
         SUM(QTDE)
      FROM CONTADORES
      WHERE CONTADORES.REG IN ('M001','M200','M210','M400','M410','M600','M610',
                               'M800','M810','M990')
      INTO :REG, :VQTD_LIN_C

     DO
      QTD_LIN_C = :VQTD_LIN_C ;

     SUSPEND;
  END

END^



SET TERM ; ^